function canReadTask(session: Session | null, task: Task): boolean {
  if (!session) return false;
  if (session.role !== 'member') return false;
  return task.ownerId === session.userId;
}

function complete(task: Task): Task {
  if (task.done) throw new Error('Task is already complete');
  return { ...task, done: true };
}

interface User { id: string }
interface Task { status: string; ownerId?: string }
function approve(task: Task, manager: User): Task {
  return { ...task, status: 'approved' };
}
